<script lang="ts">
  import type { Language } from './i18n';
  import { softwareHistory, type SoftwareHistory, type SoftwareChange } from './softwareHistory';
  import { downloadJson } from './format';
  let { language }: { language: Language } = $props();
  const it = $derived(language === 'it');
  let history = $state<SoftwareHistory | null>(null), busy = $state(false), error = $state(''), search = $state(''), page = $state(0), cursors = $state<(number | null)[]>([null]);
  const filtered = $derived((history?.entries ?? []).filter(e => `${e.after?.name ?? e.before?.name ?? ''} ${e.after?.publisher ?? e.before?.publisher ?? ''}`.toLocaleLowerCase().includes(search.toLocaleLowerCase())));
  const pages = $derived(Math.max(1, Math.ceil(filtered.length / 5)));
  const visible = $derived(filtered.slice(Math.min(page, pages-1)*5, (Math.min(page,pages-1)+1)*5));
  const date = (t: number) => new Date(t).toLocaleString(language === 'it' ? 'it-IT' : 'en-GB');
  const label = (e: SoftwareChange) => ({appeared: it ? 'Nuova voce osservata' : 'New entry observed',reappeared: it ? 'Voce ricomparsa' : 'Entry reappeared',disappeared: it ? 'Voce non più presente' : 'Entry no longer present',version_changed: it ? 'Versione cambiata' : 'Version changed',metadata_changed: it ? 'Metadati cambiati' : 'Metadata changed'}[e.kind]);
  async function load(reset = false, older = false) {
    if (busy) return; busy = true; error = '';
    const next = reset ? [null] : older && history?.entries.length ? [...cursors, history.entries.at(-1)!.sequence] : cursors.slice(0,-1);
    try { const result = await softwareHistory(next.at(-1) ?? null); history = result; cursors = next.length ? next : [null]; page = 0; }
    catch(e) { error = String(e); } finally { busy = false; }
  }
  function exportHistory() { try { downloadJson(JSON.stringify({ product: 'piko', kind: 'installer_metadata_history', export_schema_version: 1, exported_at: new Date().toISOString(), history, integrity: 'unsigned_export' }, null, 2),'events'); } catch(e) { error = String(e); } }
</script>
<details class="history-panel" ontoggle={e => { if (e.currentTarget.open && !history && !busy && !error) void load(true); }}>
  <summary>{it ? 'Storico applicazioni e versioni' : 'Application and version history'}</summary>
  <p>{it ? 'Differenze nei dati dichiarati dagli installer, rilevate aprendo o aggiornando questa sezione. Non è una verifica della firma o del comportamento del programma.' : 'Changes in installer-declared data observed when opening or refreshing this section. This does not verify signatures or app behavior.'}</p>
  <div class="toolbar"><label>{it ? 'Cerca nelle 50 variazioni caricate' : 'Search the 50 loaded changes'}<input type="search" bind:value={search} oninput={() => page = 0} maxlength="200" /></label><button class="button secondary small" disabled={busy} onclick={() => load(true)}>{it ? 'Aggiorna storico' : 'Refresh history'}</button><button class="text-button" disabled={busy || !history || !!error} onclick={exportHistory}>{it ? 'Esporta storico caricato' : 'Export loaded history'}</button></div>
  {#if busy}<p role="status">{it ? 'Lettura e confronto…' : 'Reading and comparing…'}</p>{/if}
  {#if error}<p class="warning" role="alert">{it ? 'Storico non aggiornato. I dati precedenti restano disponibili.' : 'History not refreshed. Earlier data remains available.'} {error}</p>{/if}
  {#if history}<p class="reading">{it ? 'Prima osservazione' : 'First observation'}: {date(history.first_observed_at)} · {it ? 'Ultima lettura' : 'Last reading'}: {date(history.observed_at)}</p>
    {#if !history.inventory_complete}<p class="warning">{it ? 'Inventario parziale: le voci mancanti non vengono segnate come rimosse.' : 'Partial inventory: missing entries are not marked removed.'}</p>{/if}
    {#if !filtered.length}<p>{history.entries.length ? (it ? 'Nessuna variazione corrisponde alla ricerca in questa lettura.' : 'No loaded change matches the search.') : (it ? 'Nessuna variazione osservata. La prima lettura crea il riferimento iniziale.' : 'No changes observed. The first reading creates the initial baseline.')}</p>{/if}
    {#each visible as entry (entry.sequence)}<article><div class="heading"><strong>{entry.after?.name ?? entry.before?.name}</strong><span>{label(entry)}</span></div><small>{date(entry.observed_at)}</small><details><summary>{it ? 'Vedi cosa è cambiato' : 'See what changed'}</summary><dl>{#each ['name','version','publisher','install_location'] as field}<div><dt>{({name:it ? 'Nome':'Name',version:it ? 'Versione':'Version',publisher:it ? 'Editore':'Publisher',install_location:it ? 'Cartella dichiarata':'Declared folder'} as Record<string,string>)[field]}</dt><dd>{entry.before?.[field as 'version'] ?? (it ? 'Sconosciuto':'Unknown')} → {entry.after?.[field as 'version'] ?? (it ? 'Sconosciuto':'Unknown')}</dd></div>{/each}</dl><p class="reading">{it ? 'Identità della voce di registro' : 'Registry entry identity'}: <code>{entry.after?.id ?? entry.before?.id}</code></p></details></article>{/each}
    {#if pages > 1}<div class="pager"><button class="text-button" disabled={page === 0 || busy} onclick={() => page--}>{it ? 'Precedenti' : 'Previous'}</button><span>{Math.min(page,pages-1)+1}/{pages}</span><button class="text-button" disabled={page >= pages-1 || busy} onclick={() => page++}>{it ? 'Successive' : 'Next'}</button></div>{/if}
    <div class="pager"><button class="button secondary small" disabled={busy || cursors.length<2} onclick={() => load()}>{it ? 'Letture più recenti' : 'Newer records'}</button><button class="button secondary small" disabled={busy || !history.has_more} onclick={() => load(false,true)}>{it ? 'Carica variazioni più vecchie' : 'Load older changes'}</button></div>
  {/if}
  <p class="reading">{it ? 'Conserva fino a 2000 variazioni e 4096 identità; oltre il limite di identità interrompe il salvataggio con un errore. Le variazioni più vecchie vengono eliminate. Una voce assente non dimostra una disinstallazione. Non raccoglie i cambiamenti avvenuti tra due letture e non blocca gli aggiornamenti.' : 'Retains up to 2000 changes and 4096 identities; reaching the identity limit stops saving with an error. Oldest changes are deleted. Missing entries do not prove uninstallation. Changes between readings are not collected and updates are not blocked.'}</p>
</details>
<style>
  .history-panel { background:var(--surface); border:1px solid var(--border); border-radius:16px; padding:24px; min-width:0; } summary { cursor:pointer; font-size:.85rem; } p { color:var(--muted); font-size:.8rem; margin:12px 0; } .toolbar, .pager, .heading { display:flex; gap:12px; align-items:center; flex-wrap:wrap; justify-content:space-between; } .toolbar { margin:18px 0; } label { flex:1; display:grid; gap:8px; font-size:.76rem; min-width:160px; } input { width:100%; border:1px solid var(--border-strong); border-radius:8px; padding:10px; background:var(--surface); color:var(--text); } article { padding:15px 0; border-top:1px solid var(--border); } strong { font-size:.86rem; overflow-wrap:anywhere; } .heading span { font-size:.72rem; color:var(--accent-ink); background:var(--accent-soft); border-radius:12px; padding:5px 8px; } small,.reading { font-size:.72rem; color:var(--muted); } article details { margin-top:12px; } dl { margin:8px 0; } dl > div { display:grid; grid-template-columns:140px 1fr; gap:12px; padding:8px 0; font-size:.76rem; } dt { color:var(--muted); } dd { margin:0; overflow-wrap:anywhere; } .pager { margin-top:16px; font-size:.75rem; } .warning { color:var(--warning); background:var(--warning-surface); padding:12px; border-radius:10px; } .button { white-space:normal; } @media(max-width:650px) { dl > div { grid-template-columns:1fr; gap:5px; } .history-panel { padding:18px; } }
</style>
